/*
 * THE ROSTER'S FILTER PIPELINE (TASK-L164 §3), ported from
 * src/lib/components/staff/Roster.tsx — search, cohort and programme, in that
 * file's order, as ONE pure reduction over rows already in memory. There is no
 * fetch in the product and there is none here: this is a coaching practice, not
 * a directory of thousands.
 *
 *   finished, the three steps, displayName, lastSeen -> staff/Roster.tsx
 *   the stable date format                           -> Logic/Standing (FORMAT)
 *
 * THE SELECTS' OPTIONS ARE NOT HERE: rf_opts computes them from the people and
 * the words alone, because a Dropdown handed new items snaps back to its default.
 *
 * ORDER IS NOT DECIDED HERE. The rows arrive in the server's order
 * (Data/Fixture roster) and a filter only ever removes.
 *
 * WHAT THE COACH READS IS COMPOSED HERE AND WORDED IN Data/Strings (`people`).
 * This node holds no English of its own and throws without its copy, the same
 * contract as Logic/Standing: a fallback sentence here would be a second owner.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

/* NOT ARRIVED YET IS NOT THE SAME AS WIRED WRONG. A Function runs on every
   input that lands, and the people can land before the words do — measured: the
   first render threw here, once, before Data/Strings had emitted. So an absent
   copy waits (this node runs again the moment it arrives), and a copy that
   ARRIVES without a `people` namespace is still a named failure. */
if (Inputs.copy === undefined || Inputs.copy === null) return;
const COPY = (plain(Inputs.copy) || {}).people;
if (!COPY || !COPY.lastSeen) {
  throw new Error('Logic/Roster filter: no `people` copy. Wire Data/Strings.copy into Copy (TASK-L164).');
}

function fill(template, values) {
  return String(template).replace(/\{(\w+)\}/g, (m, k) => (values[k] === undefined ? m : String(values[k])));
}

/* ── THE FILTER STATES ─────────────────────────────────────────────────────
 * Each is a readable string, and none can collide with a cohort id. They are
 * non-empty on purpose: a Dropdown option whose Value is "" is an option the
 * control cannot select back, so the product's "" sentinels become words here.
 * The meaning is unchanged. */
const ALL = 'all';
const UNFILED = 'unfiled';
const ACTIVE_PROGRAMME = 'active';
const ANY_PROGRAMME = 'any';
const FINISHED_PROGRAMME = 'finished';

/* A BUTTON, NEVER A DATE (L123 §5.1). A programme past its agreed end that
 * nobody closed is still running, which is why this needs no clock. */
function finished(p) {
  return p.archivedAt !== null && p.archivedAt !== undefined ? true : p.status === 'closed';
}

/* A person always has a name to click, however little is known about them. The
 * trainer's own label wins, because that is what a coach recognises. This is
 * NOT the chain for audience copy — that one skips projectName (L128, L165). */
function displayName(p) {
  return p.coachLabel || p.projectName || p.email || p.learnerId;
}

/* A DURATION, not a calendar date — so it reads Date.now() and never the
 * reader's timezone, and it does not go through the date formatter (L100's
 * Roster.lastSeen note). Null is "No activity yet", never "never". */
function lastSeen(iso) {
  if (!iso) return COPY.lastSeen.none;
  const days = Math.floor((Date.now() - new Date(iso).getTime()) / 86400000);
  if (days <= 0) return COPY.lastSeen.today;
  if (days === 1) return COPY.lastSeen.yesterday;
  return fill(COPY.lastSeen.days, { days: days });
}

/* The one calendar date on this page, pinned to UTC so a server and a browser
 * in different zones print the same day (L93). Same formatter as Logic/Standing. */
const FORMAT = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' });
const fmtDate = (iso) => (iso ? FORMAT.format(new Date(iso)) : '');

const people = plain(Inputs.people) || [];
const query = String(Inputs.query || '').trim();
const q = query.toLowerCase();
const cohortFilter = String(Inputs.cohortFilter || ALL);
const programmeFilter = String(Inputs.programmeFilter || ACTIVE_PROGRAMME);

const shown = people.filter((p) => {
  const programmes = p.programmes || [];
  const theirCohorts = p.cohorts || [];
  /* §3.1 — hides somebody ONLY when EVERY programme they have is finished. A
     learner with none is filtered out by neither branch: that is L89's reason
     for existing, and the half that is easy to get backwards. */
  if (programmeFilter === ACTIVE_PROGRAMME) {
    if (programmes.length > 0 && programmes.every(finished)) return false;
  } else if (programmeFilter === FINISHED_PROGRAMME) {
    if (!programmes.some(finished)) return false;
  }
  /* §3.2 — MEMBERSHIP, never equality: a learner is in many cohorts (L104). */
  if (cohortFilter === UNFILED) {
    if (theirCohorts.length > 0) return false;
  } else if (cohortFilter !== ALL) {
    if (!theirCohorts.some((c) => c.id === cohortFilter)) return false;
  }
  if (!q) return true;
  return [p.coachLabel, p.projectName, p.email].concat(theirCohorts.map((c) => c.name)).some(
    (f) => typeof f === 'string' && f.toLowerCase().indexOf(q) !== -1
  );
});

Outputs.rows = shown.map((p) => {
  /* A COUNT, presented as a count — never a percentage, a bar or a grade — and
     only when there is a path to count against. `0 of 0` is not information. */
  const setUp = p.contextVersion !== null && p.contextVersion !== undefined;
  const parts = [];
  if (!setUp) parts.push(COPY.notSetUp);
  else {
    parts.push(p.projectName || COPY.noProject);
    if (p.stepsTotal > 0) parts.push(fill(COPY.steps, { done: p.stepsComplete, total: p.stepsTotal }));
  }
  parts.push(lastSeen(p.lastActivity));
  const theirCohorts = p.cohorts || [];
  return {
    learnerId: p.learnerId,
    name: displayName(p),
    /* On every row, not only as a fallback: the one identifier that stays true
       when a label and a project name both change. Staff-only surface. */
    email: p.email || '',
    hasEmail: Boolean(p.email),
    meta: parts.join(' · '),
    /* Nothing at all for somebody nobody has filed — never the word "none". */
    cohorts: theirCohorts.map((c) => ({ id: p.learnerId + ':' + c.id, name: c.name })),
    hasCohorts: theirCohorts.length > 0,
    /* A state of the PLAN, in the row's own ink: no red, no --warm, no pill. */
    replanLine: p.replanBlockedAt ? COPY.replanBlocked : '',
    hasReplanLine: Boolean(p.replanBlockedAt),
    /* A DATE, never a count: three unanswered messages give one date. */
    awaitingLine: p.awaitingReplySince ? fill(COPY.awaiting, { when: fmtDate(p.awaitingReplySince) }) : '',
    hasAwaitingLine: Boolean(p.awaitingReplySince),
  };
});

/* TWO EMPTY STATES, AND THEY STAY DIFFERENT (§4). One is a fact about the
   platform; the other is a fact about what the coach just chose. The product
   prints `Nobody matches “”` when a FILTER emptied the list with no query typed;
   that third sentence is new here and recorded as a deviation. */
Outputs.hasRows = shown.length > 0;
Outputs.hasEmpty = shown.length === 0;
Outputs.emptyText =
  people.length === 0
    ? COPY.empty.nobody
    : shown.length > 0
      ? ''
      : query
        ? fill(COPY.empty.noMatch, { query: query })
        : COPY.empty.noMatchFilter;
Outputs.shownCount = shown.length;
Outputs.loaded();

/*
 * WHAT THE TWO SELECTS OFFER (TASK-L164 §4) — deliberately a SEPARATE Function
 * from the filter, and it reads neither filter.
 *
 * Measured, not assumed: with the options computed inside the filter, choosing
 * a cohort re-ran the filter, which re-emitted a NEW options array, and a
 * Dropdown that receives new `items` resets itself to its `value` parameter —
 * so every choice snapped straight back to "Everyone" in the same tick and the
 * select looked broken. Depending only on the people and the words is what
 * keeps these arrays stable while a coach is using them.
 *
 * STRUCTURALLY ABSENT, NEVER DISABLED: each select renders only when it can
 * change what is listed — the cohort select when somebody is in a cohort, the
 * programme select when somebody has a programme (the commerce: null posture).
 * The Values are the filter's sentinels; see Logic/Roster filter's rf_fn.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

/* NOT ARRIVED YET IS NOT THE SAME AS WIRED WRONG. A Function runs on every
   input that lands, and the people can land before the words do — measured: the
   first render threw here, once, before Data/Strings had emitted. So an absent
   copy waits (this node runs again the moment it arrives), and a copy that
   ARRIVES without a `people` namespace is still a named failure. */
if (Inputs.copy === undefined || Inputs.copy === null) return;
const COPY = (plain(Inputs.copy) || {}).people;
if (!COPY || !COPY.cohort) {
  throw new Error('Logic/Roster filter: no `people` copy for the selects (TASK-L164).');
}
const people = plain(Inputs.people) || [];

/* Every trainer-assigned cohort anybody here is in, once each, by id. Derived
 * from the rows: an empty group in the list would be a control that always
 * yields nothing. The lounge is never in `cohorts` (L104). */
const byId = {};
for (const p of people) for (const c of p.cohorts || []) byId[c.id] = c;
const cohorts = Object.keys(byId).map((k) => byId[k]).sort((a, b) => a.name.localeCompare(b.name));

Outputs.hasCohortSelect = cohorts.length > 0;
Outputs.cohortOptions = [{ Label: COPY.cohort.all, Value: 'all' }]
  .concat(cohorts.map((c) => ({ Label: c.name, Value: c.id })))
  .concat([{ Label: COPY.cohort.unfiled, Value: 'unfiled' }]);
Outputs.hasProgrammeSelect = people.some((p) => (p.programmes || []).length > 0);
Outputs.programmeOptions = [
  { Label: COPY.programme.active, Value: 'active' },
  { Label: COPY.programme.finished, Value: 'finished' },
  { Label: COPY.programme.any, Value: 'any' },
];
